compile.workshop:
variables {
    global:
        0: target
    player:
        0: playerTarget
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(target, 1);
    }
}

rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, playerTarget, Event Player);
    }
}

